identity.command:
node --input-type=module <<'JS'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { build } from 'esbuild';
import { artifactDigest } from './scripts/remediation/board.mjs';
const h = b => createHash('sha256').update(b).digest('hex');
const read = p => JSON.parse(fs.readFileSync(p, 'utf8'));
const freeze = read('docs/remediation/evidence/W03.01/integration-freeze-v1.json');
const artifact = freeze.artifact;
assert.equal(artifactDigest(artifact), '5982b2613f047f71db68f92c2cd679a099e759a27d8dee316181e6148432a16b');
const pins = artifact.files.map(x => ({...x, actual: h(fs.readFileSync(x.path))}));
for (const x of pins) assert.equal(x.actual,x.sha256,x.path);
const protectedPins = freeze.protectedPins.map(x=>({...x, actual:h(fs.readFileSync(x.path))}));
for (const x of protectedPins) assert.equal(x.actual,x.expected,x.path);
const graphRecord = read('docs/remediation/evidence/W03.01/source-inputs-v1.json');
assert.deepEqual(JSON.parse(graphRecord.execution.output), graphRecord.result);
const g = graphRecord.result;
const result = await build({entryPoints:g.entryPoints,...g.options,outdir:'/tmp/w0301-review-no-write',logLevel:'silent'});
const inputs = Object.keys(result.metafile.inputs).sort().map(path=>({path,sha256:h(fs.readFileSync(path))}));
assert.deepEqual(inputs,g.inputs);
for (const x of inputs) assert.equal(pins.find(p=>p.path===x.path)?.sha256,x.sha256,x.path);
const externals=[...new Set(Object.values(result.metafile.outputs).flatMap(x=>x.imports.filter(i=>i.external).map(i=>i.path)))].sort();
assert.deepEqual(externals,g.externals);
const before = read('docs/remediation/evidence/W03.01/before-sources-v1.json').beforeSources;
const baseline = JSON.parse(read('docs/remediation/evidence/W03.01/baseline.json').output);
for(const x of baseline.originalSources){assert.equal(h(x.source),x.sha256);assert.equal(before.find(b=>b.path===x.path)?.sha256,x.sha256);}
const worker = read('docs/remediation/evidence/W03.01/worker-checks.json');
for(const x of JSON.parse(worker.sourceFreeze.output)) assert.equal(pins.find(p=>p.path===x.path)?.sha256,x.sha256);
const deltas=before.map(x=>({...x,after:h(fs.readFileSync(x.path))}));
console.log(JSON.stringify({artifactDigest:artifact.digest,fileCount:pins.length,pins,protectedPins,localGraph:{inputs,externals,recordMatchesStdout:true,actualGraphMatches:true,allCovered:true},baselineOriginalsVerified:baseline.originalSources.map(({path,sha256})=>({path,sha256})),workerSourceFreezeMatches:true,declaredDeltas:deltas,proofHashes:['docs/remediation/evidence/W03.01/integration-freeze-v1.json','docs/remediation/evidence/W03.01/worker.md','docs/remediation/evidence/W03.01/worker-checks.json'].map(path=>({path,sha256:h(fs.readFileSync(path))}))},null,2));
JS

scopedSourceComparison.command:
node <<'JS'
const fs=require('fs'),{createHash}=require('crypto'),{execFileSync}=require('child_process'),assert=require('assert/strict');
const hash=s=>createHash('sha256').update(s).digest('hex');
const before=require('./docs/remediation/evidence/W03.01/before-sources-v1.json').beforeSources;
const expected=p=>before.find(x=>x.path===p).sha256;
const paths=['src/middleware/auth.refresh-boundary.test.ts','src/auth/signing-config.boundary.test.ts','scripts/import-content.mjs'];
let refresh=fs.readFileSync(paths[0],'utf8').replace('request(configPath, bearer(tokens.accessToken))','request(configPath)').replace('request(`/config/reflex/history?scope=${scope}`, bearer(tokens.accessToken))','request(`/config/reflex/history?scope=${scope}`)');
let signing=fs.readFileSync(paths[1],'utf8').replace("f.request('/config/reflex?scope='+scope, bearer(renewed.accessToken))","f.request('/config/reflex?scope='+scope)");
let importer=fs.readFileSync(paths[2],'utf8').replace('fetch(`${base}/content/catalog?scope=${scope}`, { headers: auth })','fetch(`${base}/content/catalog?scope=${scope}`)');
const headerOnly=[refresh,signing,importer].map((source,i)=>({path:paths[i],recoveredBeforeHash:hash(source),expected:expected(paths[i])}));
for(const x of headerOnly)assert.equal(x.recoveredBeforeHash,x.expected,x.path);
const headBased=['public/meridian/meridian.js','public/storefront.js','scripts/console-preview.sh','docs/kit/02-api-reference.md'].map(path=>({path,headHash:hash(execFileSync('git',['show','HEAD:'+path])),expected:expected(path)}));
for(const x of headBased)assert.equal(x.headHash,x.expected,x.path);
const diff=execFileSync('git',['diff','--','scripts/console-preview.sh'],{encoding:'utf8'});
console.log(JSON.stringify({headerOnly,headBased,previewDiff:diff},null,2));
